cypher:
// This query cannot be answered with the given graph schema.
// Returning all movies as a fallback
MATCH (m:Movie) 
RETURN m.title AS movieTitle
LIMIT 3

// This query cannot be answered with the given graph schema.
// Returning all movies for demonstration.
MATCH (m:Movie)
RETURN m

MATCH (q:Question)
WHERE NOT EXISTS {
  MATCH (q)-[:TAGGED]->(t:Tag)
  WHERE t.name IN ['graphql', 'apollo']
}
RETURN q

MATCH (article:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
  (org)<-[:HAS_SUBSIDIARY]-(:Organization)
}
RETURN DISTINCT article

MATCH (article:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
    MATCH (org)-[:HAS_CEO]->(ceo:Person),
          (org)-[:HAS_BOARD_MEMBER]->(ceo)
}
RETURN DISTINCT article

MATCH (org:Organization)<-[:MENTIONS]-(article:Article)
WHERE EXISTS {
  MATCH (org)<-[:HAS_BOARD_MEMBER]-(person:Person)-[:HAS_INVESTOR]->(org) 
}
RETURN DISTINCT article.title

MATCH (o:Organization)
WHERE NOT EXISTS {
  MATCH (:Article)-[:MENTIONS]->(o)
}
RETURN o.name AS organizationName

MATCH (o:Organization)-[:HAS_INVESTOR]->(:Organization)
WHERE EXISTS { (o)-[:HAS_SUPPLIER]->(:Organization) }
RETURN DISTINCT o.name

MATCH (p:Person)-[:HAS_BOARD_MEMBER]->(org:Organization)
WHERE EXISTS { (p)-[:HAS_INVESTOR]->(:Organization) }
RETURN DISTINCT org.name

MATCH (ceo:Person)-[:HAS_CEO]->(subsidiary:Organization)
WHERE EXISTS {
  (parent:Organization)-[:HAS_SUBSIDIARY]->(subsidiary)
}
RETURN ceo.name

MATCH (article:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
  MATCH (org)-[:HAS_CEO]->(ceo:Person)
  WHERE EXISTS {
    MATCH (ceo)-[:HAS_BOARD_MEMBER]->(:Organization)
  }
}
RETURN article.title
LIMIT 3

MATCH (article:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
  (org)-[:HAS_SUPPLIER]->(supplier:Organization)<-[:MENTIONS]-(article)
}
RETURN DISTINCT org.name

MATCH (parent:Organization)-[:HAS_SUBSIDIARY]->(subsidiary:Organization)
WHERE (parent)-[:HAS_CATEGORY]->() AND (subsidiary)-[:HAS_CATEGORY]->()
AND NOT EXISTS {
  MATCH (parent)-[:HAS_CATEGORY]->(parentCategory:IndustryCategory)<-[:HAS_CATEGORY]-(subsidiary)
}
RETURN DISTINCT parent.name

MATCH (o:Organization)
WHERE NOT EXISTS {
  (a:Article)-[:MENTIONS]->(o)
}
WITH avg(o.nbrEmployees) AS averageEmployees
RETURN averageEmployees

MATCH (article:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
  MATCH (org)-[:HAS_CEO]->(ceo:Person)-[:HAS_BOARD_MEMBER]->(otherOrg:Organization)
}
RETURN DISTINCT article

MATCH (o:Organization)
WHERE o.nbrEmployees > 1000 AND EXISTS {(o)-[:HAS_SUBSIDIARY]->(:Organization)}
RETURN o.name

MATCH (org:Organization)-[:IN_CITY]->(city:City)
WHERE 
  EXISTS { (org)-[:HAS_COMPETITOR]->(comp:Organization)-[:IN_CITY]->(city) } 
  AND
  EXISTS { (org)-[:HAS_SUPPLIER]->(supp:Organization)-[:IN_CITY]->(city) }
RETURN DISTINCT city.name

MATCH (art:Article)-[:MENTIONS]->(org:Organization)
WHERE EXISTS {
  MATCH (art)-[:MENTIONS]->(sub:Organization)
  WHERE (org)-[:HAS_SUBSIDIARY]->(sub)
}
RETURN DISTINCT org.name

MATCH (a:Article)-[:MENTIONS]->(o1:Organization)
WHERE EXISTS {
  MATCH (a)-[:MENTIONS]->(o2:Organization)<-[:HAS_INVESTOR]-(o1)
}
RETURN DISTINCT o1.name

MATCH (ceo:Person)-[:HAS_CEO]->(org:Organization)
WHERE EXISTS {
  MATCH (ceo)-[:HAS_CHILD]->(parent:Person)-[:HAS_BOARD_MEMBER]->(:Organization)
}
RETURN DISTINCT org.name

MATCH (o1:Organization)-[:HAS_COMPETITOR]->(competitor:Organization)
WHERE EXISTS {
  MATCH (competitor)<-[:HAS_SUPPLIER]->(:Organization)
}
RETURN DISTINCT o1.name

MATCH (org:Organization)-[:HAS_COMPETITOR]->(competitor:Organization)
WHERE EXISTS {
  (competitor)-[:HAS_INVESTOR]->(:Organization)
}
RETURN DISTINCT org.name

MATCH (org:Organization)-[:HAS_SUBSIDIARY]->(parent:Organization)
WHERE EXISTS {
  MATCH (parent)<-[:HAS_SUPPLIER]-(customer:Organization)
}
RETURN DISTINCT org.name AS organization_name

MATCH (p:Person)-[:HAS_CEO]->(o:Organization)
WHERE EXISTS { MATCH (p)-[:HAS_BOARD_MEMBER]->(otherOrg:Organization) WHERE o <> otherOrg }
RETURN DISTINCT o.name

MATCH (a:Article)
WHERE NOT EXISTS { (a)-[:MENTIONS]->(:Organization) }
RETURN avg(a.sentiment) AS averageSentiment

MATCH (o:Organization)
WHERE NOT EXISTS {
  (a:Article)-[:MENTIONS]->(o)
}
WITH avg(o.revenue) AS averageRevenue
RETURN averageRevenue

MATCH (o1:Organization)<-[:HAS_CEO]-(p:Person)-[:HAS_BOARD_MEMBER]->(o2:Organization)
WHERE EXISTS {
  MATCH (o1)-[:HAS_CATEGORY]->(ic:IndustryCategory)<-[:HAS_CATEGORY]-(o2)
}
RETURN DISTINCT o1.name

MATCH (p:Person)-[:HAS_BOARD_MEMBER]->(org:Organization)
WHERE EXISTS {
  (p)-[:HAS_CHILD]->(ceo:Person)-[:HAS_CEO]->(:Organization)
}
RETURN org.name

MATCH (f:Filing)-[:CONCERNS]->(e:Entity)
WHERE EXISTS {
  (e)-[:ORIGINATOR]->(:Filing)
}
WITH avg(f.amount) AS average_amount
RETURN average_amount

MATCH (stevron:Character {name: 'Stevron-Frey'})
CALL {
    WITH stevron
    MATCH (stevron)-[:INTERACTS|:INTERACTS1|:INTERACTS2|:INTERACTS3|:INTERACTS45]-(char1)
    RETURN collect(DISTINCT char1) AS stevron_interacted_with
}
MATCH (walder:Character {name: 'Walder-Rivers'})
CALL {
    WITH walder
    MATCH (walder)-[:INTERACTS|:INTERACTS1|:INTERACTS2|:INTERACTS3|:INTERACTS45]-(char2)
    RETURN collect(DISTINCT char2) AS walder_interacted_with
}
RETURN apoc.coll.intersection(stevron_interacted_with, walder_interacted_with) AS characters_interacted_with_both

MATCH (b:Business)<-[:REVIEWS]-(r:Review)
WHERE r.stars = {star_rating} AND r.text CONTAINS {keyword}
RETURN b.name

MATCH (m1:Movie)
WHERE EXISTS {
  MATCH (m2:Movie)
  WHERE m1.tagline = m2.title AND m1 <> m2
}
RETURN DISTINCT m1.title

// This query cannot be answered using the provided graph schema. 
// Returning an empty result.
RETURN NULL

