MATCH (s:Supplier)
WHERE NOT EXISTS {
  MATCH (c:Customer {country: s.country})
}
WITH count(DISTINCT s) AS supplierCount
RETURN supplierCount

// This query is not possible with the given schema
// Returning all orders for demonstration
MATCH (o:Order)
RETURN o

MATCH (c:Customer {customerID: 'VINET'})-[:PURCHASED]->(o:Order)
WHERE EXISTS {
  MATCH (o)-[:ORDERS]->(p:Product {productID: '72'})
}
RETURN o.orderID, o.orderDate

MATCH (o:Order)-[rel:ORDERS]->(p:Product)
WHERE EXISTS { MATCH (p)<-[:SUPPLIES]-(s1:Supplier { supplierID: '1' }) }
  AND EXISTS { MATCH (p)<-[:SUPPLIES]-(s2:Supplier { supplierID: '2' }) }
RETURN o.orderID, o.shipRegion

MATCH (e1:Entity)-[:same_name_as]->(e2:Entity)
WHERE EXISTS {
  MATCH (e2)<-[:intermediary_of]-(:Intermediary)
}
RETURN DISTINCT e1

MATCH (hkEntity:Entity {countries: "Hong Kong"})-[:registered_address]->(sharedAddress:Address)<-[:registered_address]-(otherEntity:Entity)
WHERE EXISTS {
  (otherEntity)-[:same_name_as]->(:Entity)
}
RETURN DISTINCT hkEntity.name

MATCH (q:Question)
WHERE q.answer_count > 3
AND NOT EXISTS {
  (q)<-[:COMMENTED_ON]-(:Comment)
}
RETURN q.title

MATCH (s:Stream)-[:PLAYS]->(g:Game {name: 'Rust'})
MATCH (s)-[:MODERATOR]->(u:User)
WHERE EXISTS {
  MATCH (s2:Stream)-[:VIP]->(u)
}
RETURN DISTINCT s.name

MATCH (u:User)-[:CHATTER]->(s1:Stream)
WHERE EXISTS {
  MATCH (u)-[:MODERATOR]->(s2:Stream)
  WHERE s1 <> s2
}
RETURN DISTINCT s1

MATCH (s:Stream)
WHERE EXISTS { (s)-[:VIP]->(:User) }
  AND EXISTS { (s)-[:CHATTER]->(:User) }
WITH avg(s.followers) AS average_followers
RETURN average_followers

MATCH (s:Stream)
WHERE s.followers > 5000 AND EXISTS {
  MATCH (s)-[:HAS_LANGUAGE]->(l:Language {name: 'en'})
}
AND ANY (vip IN [(s)-[:VIP]->(vip) | vip] WHERE EXISTS {
  MATCH (vip)-[:PLAYS]->(:Game {name: 'Rust'})
})
RETURN s

// Not possible to answer this question with the given graph schema. 
// Returning an empty result.
RETURN null

MATCH (neo4j:User {screen_name: 'Neo4j'})-[:POSTS]->(tweet:Tweet)<-[:RETWEETS]-(retweeter:User)
WHERE retweeter.followers > 5000 AND EXISTS {
  MATCH (retweeter)-[:FOLLOWS]->(tobias:User {screen_name: 'Tobias Lindaaker'})
}
RETURN tweet

MATCH (neo:User {name: 'Neo4j'})<-[:FOLLOWS]-(follower:User)-[:POSTS]->(tweet:Tweet)-[:MENTIONS]->(mentioned:User)
WHERE EXISTS {
  MATCH (mentioned)-[sim:SIMILAR_TO]->(similarUser:User)
  WHERE sim.score > 0.6
}
AND EXISTS {
  MATCH (tweet)<-[:RETWEETS]-(retweet:Tweet)-[:CONTAINS]->(link:Link {url: 'your_link_url_here'})
}
RETURN DISTINCT follower.screen_name

MATCH (neo4j:User {name: "Neo4j"})<-[:INTERACTS_WITH]-(interactedUser:User)-[:POSTS]->(tweet:Tweet)<-[:RETWEETS]-(rtUser1:User)
WHERE EXISTS {
  MATCH (rtUser1)-[:USING]->(:Source {name: "specific_source_name"})
}
AND EXISTS {
  MATCH (rtUser1)-[:SIMILAR_TO {score: {gt: 0.6}}]->(similarUser:User)-[:RETWEETS]->(tweet)
}
RETURN DISTINCT interactedUser.screen_name
